    col = mix(col, gLo * 0.4, smoothstep(edge - 0.05, edge - 0.01, r)); // the dark lip
    col += vec3(1.0, 0.95, 0.8) * exp(-pow((uv.x * 0.8 - uv.y * 0.6 - param) / 0.12, 2.0)) * 0.35 * step(0.64, r);
